const input = String($json.body?.playerChoice ?? '').trim().toLowerCase();
const aliases = {
  rock: 'rock', paper: 'paper', scissors: 'scissors',
  '바위': 'rock', '보': 'paper', '가위': 'scissors',
};
const player = aliases[input];

if (!player) {
  return [{ json: {
    ok: false,
    error: 'playerChoice에 rock, paper, scissors 중 하나를 입력하세요.',
    examples: ['rock', 'paper', 'scissors', '가위', '바위', '보'],
  } }];
}

const choices = ['rock', 'paper', 'scissors'];
const labels = { rock: '바위', paper: '보', scissors: '가위' };
const computer = choices[Math.floor(Math.random() * choices.length)];
const beats = { rock: 'scissors', scissors: 'paper', paper: 'rock' };
const result = player === computer ? 'draw' : beats[player] === computer ? 'win' : 'lose';
const resultLabels = { win: '승리', lose: '패배', draw: '무승부' };

return [{ json: {
  ok: true,
  player: labels[player],
  computer: labels[computer],
  result,
  resultLabel: resultLabels[result],
  message: `내 선택: ${labels[player]} | 상대 선택: ${labels[computer]} | 결과: ${resultLabels[result]}`,
} }];
